content.text:
The evidence points to one fault: a loss-type network fault on the route-plan→route-service connection, with the impact propagating from route-plan to travel-plan to ui-dashboard. The other quiet services (consign-price, cancel) show only low-volume user-journey changes, not faults.

```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, COUNT(*) n, SUM(CASE WHEN duration > 1e9 THEN 1 ELSE 0 END) over_1s, MAX(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Route-plan outgoing GET calls: 10 of 112 exceed 1 s, max about 131 s, with no downstream server span."
        },
        {
          "kind": "trace",
          "sql": "SELECT COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM normal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' AND span_name='GET'",
          "claim": "Normal period: route-plan GET client calls never exceed 1 s, p99 about 28 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' per, SUM(value) s FROM normal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%route-plan%' AND attr_destination LIKE '%route-service%' UNION ALL SELECT 'abnormal', SUM(value) FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%route-plan%' AND attr_destination LIKE '%route-service%'",
          "claim": "TCP flag events on route-plan to route-service rose from 879 to 1689, consistent with SYN retransmits on that connection."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' per, COUNT(*) n FROM normal_traces WHERE service_name='ts-route-service' AND span_name='GET /api/v1/routeservice/routes/{start}/{end}' UNION ALL SELECT 'abnormal', COUNT(*) FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name='GET /api/v1/routeservice/routes/{start}/{end}'",
          "claim": "Route-service server spans for GET routes/{start}/{end} fell from 69 to 1, so requests from route-plan stopped arriving."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, COUNT(*) n, SUM(CASE WHEN attr_status_code='STATUS_CODE_ERROR' OR attr_http_response_status_code>=500 THEN 1 ELSE 0 END) errs, MAX(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' AND span_name LIKE '%minStation%' GROUP BY ALL",
          "claim": "Travel-plan minStation server spans take about 130 s and return HTTP 500 after route-plan's hung calls."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, MAX(duration)/1e6 max_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL",
          "claim": "Dashboard travelPlan requests inherit the roughly 130 s travel-plan latency in the abnormal period."
        }
      ]
    }
  ]
}
```

